oxy_webhelp_navlinks = {"ir_identity_summary-d39536e57573":{"topics":[{"title":"Secrets for service principals","shortdesc":"<p class=\"shortdesc\">The Overview tab for a Microsoft Entra ID service principal displays a Secrets node         in the identity graph that shows the client secrets associated with the service         principal.<\/p>","href":"identity_resilience\/ir_nhi_secrets.html","attributes":{"data-id":"ir_nhi_secrets"},"menu":{"hasChildren":false},"tocID":"ir_nhi_secrets-d39536e57586","topics":[]},{"title":"API permissions","shortdesc":"<p class=\"shortdesc\">The API Permissions tab lists the Microsoft Graph API permissions that a Microsoft         Entra ID service principal has, including privilege status and unique         identifiers.<\/p>","href":"identity_resilience\/ir_identity_api_perms.html","attributes":{"data-id":"ir_identity_api_perms"},"menu":{"hasChildren":false},"tocID":"ir_identity_api_perms-d39536e57597","topics":[]},{"title":"Memberships","shortdesc":"<p class=\"shortdesc\">The Memberships tab displays the privileged memberships and roles associated with an         identity.<\/p>","href":"identity_resilience\/ir_identity_memberships.html","attributes":{"data-id":"ir_identity_memberships"},"menu":{"hasChildren":false},"tocID":"ir_identity_memberships-d39536e57608","topics":[]},{"title":"Viewing the identity summary","shortdesc":"<p class=\"shortdesc\">View the identity summary page to investigate identities suspected of compromise or         non-compliance.<\/p>","href":"identity_resilience\/ir_viewing_identity_summary.html","attributes":{"data-id":"ir_viewing_identity_summary"},"menu":{"hasChildren":false},"tocID":"ir_viewing_identity_summary-d39536e57619","topics":[]},{"title":"Managed identities and agent identities","shortdesc":"<p class=\"shortdesc\">Managed identities and agent identities are types of service accounts used in         Microsoft Entra ID to interact securely with <span class=\"ph\">RSC<\/span> and cloud         environments.<\/p>","href":"identity_resilience\/ir_managed_id_agent_id.html","attributes":{"data-id":"ir_managed_id_agent_id"},"menu":{"hasChildren":false},"tocID":"ir_managed_id_agent_id-d39536e57630","topics":[]},{"title":"Application access for Entra ID identities","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> maps how Entra ID users gain access to enterprise applications         and tracks the downstream impact of identity changes on application access.<\/p>","href":"identity_resilience\/ir_app_access.html","attributes":{"data-id":"ir_app_access"},"menu":{"hasChildren":false},"tocID":"ir_app_access-d39536e57644","next":"ir_app_access-d39536e57644"}]}};